16	//	p300 校正前 (3,2,h=π/2)
17	//
18	// 锚点 100 校正到目标 (10,20,h=0)，整体旋转 δ=-π/2：
19	//
20	//	p100 校正后 (10,20,h=0)
21	//	p200 校正前相对锚点 (2,0) 旋转后 (0,-2) → (10,18,h=0)
22	//	p300 校正前相对锚点 (2,2) 旋转后 (2,-2) → (12,18,h=0)
23	func buildGeometryMap(t *testing.T, path string, merge float64) {
24		t.Helper()
25		m, err := Create(path, Config{
26			InitialTime: 0, InitialX: 0, InitialY: 0, InitialHeading: 0,
27			InitialVariance: 1, MaxInterval: 100, MergeDistance: merge,
28		})
29		if err != nil {
30			t.Fatal(err)
31		}
32		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
33			// 运动前朝向 0：前进 1 到 (1,0)，随后朝向转到 π/2。
34			{Time: 100, DX: 1, DY: 0, DHeading: math.Pi / 2},
35			// 运动前朝向 π/2：自身 (0,-2) 即地图 (2,0)，到 (3,0)。
36			{Time: 200, DX: 0, DY: -2},
37			// 运动前朝向 π/2：自身 (2,0) 即地图 (0,2)，到 (3,2)。
38			{Time: 300, DX: 2, DY: 0},
39		}}); err != nil {
40			t.Fatal(err)
41		}
