79	// 每一帧都必须符合同一次平移和旋转：锚点、中间帧、末帧的校正后位置或朝向
80	// 被改成另一个有限值（时间、方差、路标列表仍满足既有检查）都按损坏拒绝；
81	// 只有锚点与末帧正确而中间一帧位置偏离或单独转向也不例外。
82	func TestOpenRejectsInconsistentCorrectionGeometry(t *testing.T) {
83		cases := []struct {
84			name string
85			fn   func(fd *fileData)
86		}{
