88				fd.Corrections[0].Poses[0].After.X = 10.5
89			}},
90			{"anchor corrected y changed", func(fd *fileData) {
91				fd.Corrections[0].Poses[0].After.Y = 20.5
92			}},
93			{"anchor corrected heading changed", func(fd *fileData) {
94				fd.Corrections[0].Poses[0].After.Heading = 0.01
95			}},
96			{"middle frame position drifted while anchor and last stay right", func(fd *fileData) {
97				fd.Corrections[0].Poses[1].After.X = 10.5
98			}},
99			{"middle frame y drifted", func(fd *fileData) {
100				fd.Corrections[0].Poses[1].After.Y = 17.5
