97	// 的出现编号；known 为假表示该路标没有登记归属边界，known 为真而返回
98	// 0 表示该时间不属于它的任何一次出现。
99	func (r *observationReplay) occurrenceOf(id string, t int64) (num int, known bool) {
100		wins, ok := r.windows[id]
101		if !ok {
102			return 0, false
103		}
104		return occurrenceNumberAt(wins, t), true
105	}
106	
107	// occurrences 返回一个路标登记的出现次数；未登记时返回 0。
108	func (r *observationReplay) occurrences(id string) int {
109		return len(r.windows[id])
110	}
111	
112	// observed 归组一段帧序列中实际观测到的（路标，出现编号）：每条观测各
113	// 归组一次，同一出现只记一次；无法归组的观测（路标未登记或不属于任何
114	// 出现）不记入。帧序列只需给出时间与观测，位姿不参与归组。
115	func (r *observationReplay) observed(frames []replayFrame) map[occurrenceKey]struct{} {
116		out := make(map[occurrenceKey]struct{})
117		for _, fr := range frames {
118			for _, ob := range fr.observations {
119				if num, known := r.occurrenceOf(ob.ID, fr.time); known && num != 0 {
120					out[occurrenceKey{id: ob.ID, num: num}] = struct{}{}
121				}
122			}
123		}
124		return out
125	}
126	
127	// replay 逐帧重放观测：帧必须按时间升序给出，同帧观测按输入次序逐条
128	// 接纳。全部接纳返回 nil；否则返回第一条无法接纳的观测（已接纳的观测
129	// 留在聚合中，由调用方决定整次拒绝后如何处理——两种调用方都在校验全部
130	// 通过前不触碰真实状态）。
131	func (r *observationReplay) replay(frames []replayFrame) *replayReject {
132		for _, fr := range frames {
133			for _, ob := range fr.observations {
134				num, known := r.occurrenceOf(ob.ID, fr.time)
135				if !known {
136					return &replayReject{reason: replayUnknownLandmark, time: fr.time, id: ob.ID}
137				}
138				if num == 0 {
139					return &replayReject{reason: replayNoOccurrence, time: fr.time, id: ob.ID}
140				}
141				a := r.aggs[occurrenceKey{id: ob.ID, num: num}]
142				if a == nil {
143					continue // 该次出现未登记：不参与本次重建
144				}
145				switch a.admit(fr.pose, ob, r.mergeDistance) {
146				case obsNonFinite:
147					return &replayReject{reason: replayNonFinite, time: fr.time, id: ob.ID, num: num}
148				case obsConflict:
149					return &replayReject{reason: replayConflict, time: fr.time, id: ob.ID, num: num}
150				}
151			}
152		}
153		return nil
154	}
155	
156	// agg 返回某次出现当前重建出的聚合（计数与等权平均位置）；该出现未登记
157	// 时返回 nil。
158	func (r *observationReplay) agg(id string, num int) *observationAgg {
159		return r.aggs[occurrenceKey{id: id, num: num}]
160	}
